# Rakam (11)_compressed.pdf — Türkçe çeviri
# t(sayfa, konum, metin) = gönderi metni   |   h(sayfa, konum, metin) = görsel kartın başlığı
# Yalnızca tırnakların içindeki Türkçe metni değiştirin; sayfa ve konum sayılarına dokunmayın.


# ───────── Sayfa 1 ─────────
h(1, 1200, """Irak'ta bir aşiret bir kızın kanını döktü, sonra topluca kutlama yaptı! Uzak olmayan bir gün geliyor; o gün bıyıklar ayaklar altına alınacak""")
h(1, 2200, """Kötü zamanı, insanların her gün ve her yerde horozlar gibi dalaştığını gördüğünde tanırsın!""")

# ───────── Sayfa 2 ─────────
t(2, 440, """Bir asırdır Sahra altı Afrika'ya pek çok milyar pompalandı; sonuç ise daha fazla korkunç yoksulluk oldu. Çünkü Sahra altı devletleri parayı bir tahakküm ve hâkimiyet aracı olarak kullandı; olgun devletler ise parayı bir gelişme aracı olarak kullandı. Dolayısıyla gelişme asla sırf paraya sahip olmakta değildir; para tek başına gelişme üretmez. Önemli olan, liderin parayla birlikte plana, fikre, modele, gerçeği okumada derinliğe, geleceğe dair basirete, muhasebe kurumlarına, performansta gerçek kaliteye sahip düzenleyici hükümet kuruluşlarına ve şeffaf bir denetim mekanizmasına sahip olmasıdır.""")
h(2, 1100, """İnsanların hayatında para ya yalnızca güçtür ya da gelişme içindir. Firavun ve Karun onu yalnızca güç olarak kullandılar! Peygamber ve halifeleri ise onu gelişme için kullandılar""")
t(2, 1830, """Hani himmet, hani gençlik, hani hayatın son anına dek kalması gereken o delikanlılık? Bu gevşekliği yaşayan babalar, bilin ki ona varacaksınız; fakat ona vardığınızda kendinize verdiğiniz zararın boyutunu keşfedeceksiniz. Çünkü bugünün dünyasında çocuklarınız kendilerine zar zor harcıyor; yakınlarına yardım edebilecekleri bir geçim genişliğinde olanlar ise azdır.

Kimseye muhtaç olmadan yaşayıp ölen sahâbe gibi güçlü olun! Kendini hor gören horluğa varır .. Sağlığınıza özen gösterin; onu ne bir oğula ne bir kıza harcayın. Çocuklarınıza mümkün olanı ve Rabbinizin Kitabı'nın belirlediği vacibi sunun; sakın ha onlar uğruna sağlığınız, şahsî hayatınız ve saadetiniz pahasına fedakârlık etmeyin. Sakın ha, sonra yine sakın ha; bin kere, bin kere sakın ha!

Size Allah'tan başkası fayda vermez; sağlıkla kalmanın sebeplerine sarılın, sağlığınızı heba edip de "Yarın çocuklarımız bizi evin içinde taşır!" demeyin. Sizi kimse taşımayacak ey saflar! Bir mahlûka yük olarak yaşamayın. Neden böyle sefil ve kötü bir hayat istiyorsunuz?! Yemek, rahat sevgisi ve döşeklere serilmek karşılığında dilediğinizi yiyip kemiklerinize, bedenlerinize ve sağlığınıza gevşeklik getirmek; sonra da bitkin hastalar olarak yaşayıp, yılda bir kez gelebilecek çocuklarınızdan bir anlık değerli ilgi beklemek için mi; hem de onlar çağların en kötülerinden ve en şerlilerinden bir çağdayken?! Akılları, bugünkü pek çok aklın sefaleti gibi sefil olmayan sahâbeye uyun. Ölüme dek genç olun; daha önce efendilerde bulunmayan, yalnızca onların avamında bulunan tercihleri seçmeniz yeter artık .. Efendilerin hayatını yaşayın ve efendilerin aklıyla düşünün.""")

# ───────── Sayfa 3 ─────────
h(3, 400, """Şaşılacak babalar; vallahi anlamıyorum, anlamayacağım da! Sıddîk'ın, Fârûk'un, Osman'ın, Ebu'l-Haseneyn'in ve Hâlid'in "Çocuklarımızı, yaşlılığımızda bizi taşısınlar diye yetiştiriyoruz" dediklerini gördünüz mü?!!""")
t(3, 1100, """Bu kara âkıbetten evlatların pek azı kurtulur""")
h(3, 1500, """Kavga eden eşler; içten içe sarsılmış, dünyadan ve insanlardan titreyen çocuklar yetiştirir!""")

# ───────── Sayfa 4 ─────────
h(4, 300, """Cehalet ne zamana kadar? Seçilmiş şerefli bir peygamber; "Müslümanlar" onun adını en aşağılık fiillerden birine yapıştırıyor!""")
t(4, 820, """Müslüman babalardan ve annelerden milyonlarcası boğulmuş durumda .. Kıyamet günü hatalardan dağlar içinde boğulmuş .. Koca koca dağlar!""")
h(4, 1300, """Felaket getiren çirkin kolektif düşüncenin elekten geçirilmesi! Bir buçuk yıl önce bir anneye dedim ki: "Çocuklarının gıybetini yapmak senin hakkın değil"; hayrete düştü!!""")
t(4, 1990, """Ümmetler, dışarıya gösterdikleri dikkat kadar içeriye de dikkat ettiklerinde hayır içinde yaşar! İnsan da nefsine karşı uyanık olduğunda hayır içinde yaşar; çünkü nefsi onun içerideki düşmanıdır. İnsan, kolektif düşünceye karşı uyanık olduğunda sözde ve amelde dosdoğru olur; çünkü o düşünce daima elekten geçirilmeye muhtaçtır!""")
h(4, 2400, """İnsan, kalbinden, karaciğerinden veya pankreasından ansızın vurulduğunda uyanır; fakat derisinden, saçından ve parmaklarından ansızın vurulduğunda uyanmaz!""")

# ───────── Sayfa 5 ─────────
t(5, 690, """Bunu 2011'de, İbrânî Baharı devrimleri tutuştuğunda söylemiştim .. Fakat heyhat .. Allah Teâlâ'nın kaderi daima ve ebediyen her şeyin üstündedir.""")
h(5, 1200, """Bin kere bin ses tek bir mazluma yardım edemez; ama tek bir yüce söz bütün mazlumlara yardım eder!""")
h(5, 2200, """Zalim, zulmettiği kimseye Allah'ın yardımını görünceye dek zulmünü görmez!""")

# ───────── Sayfa 6 ─────────
t(6, 320, """Mahkemelerde ve hâkimlerin önünde, suç işleyenlerin hepsi itiraf eder!""")
h(6, 800, """Zalim, ezici bir üst güç onu bakmaya zorlayıncaya dek zulmünü görmez!""")
h(6, 1900, """Zalim bir nefis, toplumdan hakka tam bir boyun eğiş görünceye dek caymaz!""")

# ───────── Sayfa 7 ─────────
h(7, 500, """İnsanlar, zulüm işlemelerinin âkıbetlerini öğreninceye dek âdil hükümlere razı olmazlar!""")
h(7, 1600, """İnsanlar arasında hüküm vermekle imtihan edilen kişinin bin aklı, bin anlayışı ve bin basireti olmalıdır!""")
t(7, 2455, """24 saat "Ömrümü onunla feda ettim, onun çocuklarıyla ilgilenirken gençliğimi heba ettim!" diyen kadınlara; ve 24 saat "Çocuklarıma harcamak için gençliğimi heba ettim!" diyen erkeklere: Fıtratın tersyüz olması yeter artık! Sen, yalnızca onun çocuklarına değil, kendi çocuklarına bakmak için evlendin ve doğurdun! Bu senin görevin, keyfine kalmış değil; "onun çocuklarına bakarak ömrünü heba ettin" diye bir şey de yok. Sanki çocuklarını kaldırımdan getirmiş de sana "Bunlarla ilgilen" demiş; yahut sanki onlar başka bir kadından olan çocuklarıymış da sana "Bunlarla ilgilen" demiş! Bütün bu sözler şu an sosyal medyada yayılmış durumda ve bu kadınlar kendilerine inanıyor! Videolarda görünen babalar da: "Çocuklarıma harcamak için gençliğimi heba ettim!" Sübhânallah. Onlara kim harcayacaktı?! Toplum mu? Onları dünyaya getiren sen değil misin? …""")

# ───────── Sayfa 8 ─────────
t(8, 60, """… dünyaya getiren! Yoksa sabah uyandın da onları evinde, gökten inmiş mi buldun? İnsanların akılları eğrildi; bu dünyada akıllılardan ancak pek azı kaldı. Sosyal medya bize dünyanın bugün nerede durduğunu ve insanların hayatı ve hayatın hakikatlerini sapkın, sağlıksız biçimde anlamasının ölçeğinde hangi sınıra vardığımızı gösterdi. Kocasıyla anlaşmazlığa düşen her kadın: "O zalim, ben onun çocuklarına bakarken gençliğimi heba etti!" Yalnızca onun çocukları mı? Peki senin hayattaki görevin aslında bundan başka nedir?!""")
h(8, 600, """Annenin çocuklarına bakması vaciptir, keyfine kalmış değildir. Babanın çocuklarına harcaması vaciptir, keyfine kalmış değildir!""")
t(8, 1370, """Yeryüzüne savaşmak için indirildi; bu yüzden, bütün yeryüzü yalnızca onun olduğu halde, sadece günlük azığıyla ilgilendi; yalnızca günlük azığını dert edinmeyi sürdürdü. Bil ki ey insan, savaşçı zengin olamaz! Savaşçı servete düşkün olamaz .. Servet, silah bırakmanın anahtarlarıdır! İnsanlık tarihinde hiçbir servet yoktur ki, takvâ sahiplerinin en takvâlısının nefsi üzerinde bile bir tozu ve izi olmasın!""")
h(8, 1900, """Babamız Âdem yeryüzüne savaşmak için indirildi; öyleyse bana "Dünyaya sahip olmak için yaşa" deme; çünkü ben yalnızca babamın mirasına icabet ederim!""")

# ───────── Sayfa 9 ─────────
h(9, 400, """Babamız Âdem yeryüzüne savaşmak için indirildi. Bil ki şeytan karşısında silahını bıraktığın an, babanın mirasından vazgeçtiğin andır!""")
t(9, 1195, """Hayalî bir sahnede! Söyleyecek bundan başka bir cevap bulamaz! Yalnızca bunu söyler!""")
h(9, 1600, 'Kıyamet günü sapmışa ve şaşkına "Emanet nerede?" denir; o da şöyle der: "Yüz bin dolar, 20 çocuk, 3 villa, beş araba ve 10 bahçe yüzünden helâk oldum!"')

# ───────── Sayfa 10 ─────────
h(10, 300, """1945 dünyası seni hayatta 10000 hayalî başarıya inandırdı! Gerçek başarıların her anlamını da senden gizledi!""")
h(10, 1300, 'Zalim hikmet sözlerini okur da şöyle der: "Süslü laf! Ha! Ha! .. Bu ne diyor?! Anlamıyorum!"')
t(10, 2005, """Günaha ve karıştırmalarına ortak oldular, ama itiraf etmiyorlar!""")
h(10, 2300, """Biliyor musun: Milyonlarca mazlum aslında zalimdir?!""")

# ───────── Sayfa 11 ─────────
h(11, 1000, """Zalimler Kur'an'ı okurlar; onlara "Ne kavradınız?" denir; onlar da: "Ha? Ha? Ne demek istiyorsun? Kavradık mı? Ne kavradık?!" derler""")
h(11, 2100, """Yalnızca bedenini inşa etmekle yetinme. Nefse, ağır bir demirin ağırlığından bin kere bin kat daha önemli yükler yüklenir!""")

# ───────── Sayfa 12 ─────────
h(12, 700, """İncecik bir hikmet kılı, bir serkeşe direnmek ile bir serkeşe zulmetmeyi birbirinden ayırır!""")
t(12, 1410, """Özellikle "dine sürtünenler"; onlar fâsıklardan önce düşmandır ve tehlikeleri fâsıkların tehlikesinden az değildir; çünkü fısk ehli insanlara gizli değildir.""")
h(12, 1900, """İnsanları saptıran, konuşan bir şahsiyetin ahlâk bozukluğunu açıklamakta zulüm yoktur!""")

# ───────── Sayfa 13 ─────────
t(13, 65, """Genel bir zulme insanlara konuşarak direnmek toplumda fitne çıkarmaktır! Şahsî ve toplumsal zulme direnmekte ise, aile, sülale ve dar sosyal çevre içinde şahsî zulme direnmek ile ahlâk dışı baskınlar düzenleyip bunları zulme direniş saymak arasında ince bir çizgi vardır. Şahsî zulme direnmenin esası "zarar vermek de zarara zararla karşılık vermek de yoktur"dur .. "Sizin dininiz size, benim dinim bana" .. "Sizi terk ediyorum ve Rabbime dua ediyorum" .. Aile içi zulme direnmenin en büyük örneklerinden ikisi, Halîlürrahmân'ın (aleyhi's-salâtü ve's-selâm) örneği ile Peygamberimizin (s.a.v.) örneğidir.""")
h(13, 600, """Zulme direnme kavramı ile saldırganlık kavramı arasındaki fark muazzamdır!""")
h(13, 1800, """Kaçınılmaz beşerî çatışmanın bedelini ödememeyi seçip de "Kişiliğim neden zayıf?!" diyen kimseye şaşarım""")
t(13, 2500, """İşte şunların ve bunların arasından seçkinler çıkarılır! Beden mükemmelliğinin değil, nefis mükemmelliğinin kahramanları olmak üzere seçilenler!""")

# ───────── Sayfa 14 ─────────
h(14, 400, """İnsanların "çoğu" zalim olarak yaşama kararı alır; mazlumların çoğu da mazlum olarak yaşama kararı alır!""")
t(14, 1130, """Kol kasları ancak (direnç) denilen bir spor kullanılarak inşa edilir! Nefsin kasları da tıpkı böyle, ancak direnişle inşa edilir!""")
h(14, 1600, """Muazzam ruhî güç, nefsin kaslarıdır; tıpkı adamın kol kaslarını inşa etmesi gibi!""")
t(14, 2330, """Allah Teâlâ'nın gücüyle şu tekrarlanan soruyu cevaplamaya devam ediyorum .. Bu zor zamanda nasıl güçlü olurum .. Yeni bir cevap resimde. Önemli olan, bütün bunların Allah Teâlâ katından isabetli ve muvaffak kılınmış olmasıdır; çünkü kulun kendisinden ne bir güç ne bir kuvvet vardır; güç ve kuvvet yalnızca Allah Teâlâ'dandır""")

# ───────── Sayfa 15 ─────────
h(15, 400, """Muazzam ruhî güç; zalimlerle her gün verilen çetin bir yüzleşmenin ve aklın hayalini aşan bir iradeye sahip, asla teslim olmayan bir ruhun ürünüdür!""")
t(15, 1000, """İspanya'nın, Batı mutabakatı ve Batı desteğiyle arabulucu rolü oynamadaki geçmiş örnekleri! Emanete riayeten hiç dokunulmadan ((aktarılmış)) bilgiler; tarihin neredeyse bütün duraklarında Batı'dan etkilenen dünya siyasetini takip edenin siyasi kültürüne katkıda bulunmalıdır.

İspanya, Avrupa ile Arap dünyası arasında bir bağ olan coğrafi konumundan yararlanarak, özellikle Ortadoğu çatışmalarında stratejik arabulucu rolü oynamada uzun bir tarihî geçmişe sahiptir. İşte İspanya'nın bu rolü somutlaştırdığı en öne çıkan duraklar:

Madrid Barış Konferansı (1991): İspanyol arabuluculuğu tarihinin en önemli durağı sayılır; Madrid, İsrail ile Arap devletleri (Suriye, Lübnan, Ürdün) ve Filistinliler arasındaki ilk doğrudan yüz yüze müzakerelere ev sahipliği yaptı. Bu konferans sonradan Oslo anlaşmalarının yolunu açtı; İspanya o sırada "tarafsız bir toprak" ve bütün taraflarca kabul gören bir ülke sayıldı.

Askerî üslerin yasaklanması (1973 Savaşı): Ekim 1973 Savaşı sırasında İspanya (o sırada Franco yönetiminde olmasına rağmen), Amerika Birleşik Devletleri'nin İsrail'e silah ikmali için topraklarındaki askerî üsleri kullanmasına izin vermeyi reddederek "adaletten yana bir arabulucu" tavrı aldı; bu da Arap devletlerinin ona güvenini pekiştirdi.

Akdeniz'de Arabuluculuk Girişimi (2012): İspanya, Fas ile iş birliği içinde, diyalog kültürünü güçlendirmek ve bölgesel anlaşmazlıkları büyümeden önlemek için "Akdeniz'de Arabuluculuk Girişimi"ni başlattı.

Medeniyetler İttifakı (2004): Madrid tren bombalamalarından sonra eski İspanya Başbakanı "José Luis Zapatero", aşırılıkla askerî çatışma yerine kültürel ve dinî diyalog yoluyla mücadele etmek üzere Birleşmiş Milletler'de "Medeniyetler İttifakı" girişimini başlattı; bu da Madrid'i önleyici diplomasinin bir merkezi yaptı.

(KAICIID) Merkezi'nin kurulması: İspanya, dinî arka planı olan çatışma bölgelerinde iletişim köprüleri kurmak amacıyla 2012'de Uluslararası Dinler ve Kültürler Arası Diyalog Merkezi'nin (şimdiki merkezi Lizbon) kuruluşuna katıldı.""")
h(15, 2350, """İspanya, Batı köprüsü. Kullanılan ülke değişse de tekrarlanan eski bir Batı stratejisi!""")

# ───────── Sayfa 16 ─────────
t(16, 650, """İspanya'nın Batı'ya karşı sözde ayaklanması üzerine ve saflardan birinin ((örnek)) İspanya'nın geçişini tahlil edip onu İslâm ümmeti için müjdelerden saydığında nasıl düşündüğü üzerine bir yorum?! TikTok'un, anlamaya asla ulaşamayacak akıllar inşa etmesine bir örnek; çünkü TikTok herhangi bir akıl inşa edilecek yer değildir!

Tarihte, yakın bir küresel çatışmanın ortasında çeşitli sebeplerle önceki davranışın tersine ani bir siyasi geçişin yaşanması tekrarlanan bir şeydir. Şaşılacak olan, birinin İspanya'nın Avrupa'ya ve Amerika Birleşik Devletleri'ne düşman olduğuna ve Çin'e bağlı hale geldiğine inanmasıdır! Bu boyutta bir saflık tasavvur edilemez! İspanya Avrupa'da bir köy değildir; jeopolitik çevresine bağlı ihtiyaçları tarihî bir ihtiyaçtır ve kendisinden binlerce kilometre uzaktaki bir Çin'e yeniden yönlendirilemez. İspanyollar, Amerika, Almanya ve Fransa'nın Çin'i nasıl kolladığını çok iyi bilirler. Fakat birinin insanlara "İspanya Çin'in yanına geçti" dediğini duymak; aklı haberlerin yayımladığı şeyler üzerinden çalışıyor ve bu düzeyde bir yüzeyselliğe sahip; öyle ki beynini asıl şekillendiren tarih, siyaset, siyasi mantık ve 1945 dünyasına dair modern tarihî bakış okuması değil, haberdir. İşte bu, saf bir akıldan çıkıp dinleyenlerin bir kısmının akıllarına dökülen bir bilinç sorunudur; bu yüzden internet denen şeyden nefret ettik. İspanya, Amerika Birleşik Devletleri ile anlaşarak bir rol oynuyor; bu, Batı'nın ihtiyaç duyacağı lojistik, psikolojik ve siyasi bir roldür ve çok uzun sürmeyecektir; çünkü İspanya'nın ağırlığı büyük değildir; yalnızca gelecekte siyasi veya lojistik, yahut her ikisi birden bir arabulucu yapılması isteniyor. Fakat bu örnek saf, karşısına çıkan her habere inanmaya ne kadar da hazır; takipçilerine İspanya'nın Batı sisteminden çıktığının delilinin, bu yıl Yahuda'nın kuklasını yakmak yerine "kokuşmuş"un kuklasını yakması olduğunu haber veriyor! Bu tür saflığın sebebi, insanın devletlerin içeriden ve dışarıdan nasıl yönetildiğini anlamaya güç yetirememesi ve tarih okumasının bulunmamasıdır; zira TikTok kültürü bir akıl inşa edemez.""")
h(16, 1900, """Amerikan mutabakatıyla siyasi yeniden konumlanma. İspanya'yı Çin'in müttefiki saymak saflıktır!""")
t(16, 2515, """Ahmak, ömrünü görmeden, bakmadan, anlamadan ve idrak etmeden yaşar; sonra hayatı çöker de içinde ebediyen mahpus olarak yaşar; çünkü zalimin kaderi, istinafı kabul etmeyen bir hâkimdir""")

# ───────── Sayfa 17 ─────────
h(17, 1500, """Ruhî güç bedava değildir! O; eritilmek, dayanıklılık, sabır, dövülmek ve vazgeçmektir""")

# ───────── Sayfa 18 ─────────
h(18, 300, """Zirveden sonraki dünya, zirveden önceki dünyaya benzemeyecek!""")
t(18, 840, """Göğüs her daraldığında ((hemen)) Allah Teâlâ'yı zikret; çünkü o, tesiri hızlı, büyük panzehirdir; etkisi aynı anda olur, gecikmez. Gücün yettiğince hiçbir sebep seni bundan alıkoymasın! Zira göğüs darlığı bedeni ve ruhu yiyen bir zehirdir; Yüce Allah'ın zikri ise etkisi büyük olandır.

İsimleri ve sıfatları mukaddes, göklerde ve yerde yüce, pek büyük bir yücelikle yüce olan Yüce Rabbimiz şöyle buyurur: {Onlar iman edenler ve kalpleri Allah'ın zikriyle mutmain olanlardır. Bilin ki kalpler ancak Allah'ın zikriyle mutmain olur}""")
h(18, 1500, """Allah'ın zikri, yorgun kalbin kendisiyle pekiştirildiği en büyük şeylerdendir""")
t(18, 2215, """İftira, yalan, sahtekârlık ve aldatmaca uyduran, kendini apaçık hakkın üstünde büyüten, benliğini apaydınlık doğrunun üstünde yücelten herkesin âkıbeti bu olacaktır! Bir söz ve onun üstünde bir âyet, bazılarına isabet etti; fette, paça ve baş soğan ehlinden, her şeyi .. her şeyi yemeye çağıranlardan bazılarına .. İnsanların onların saçma bölümlerine yaptığı yorumlar; saldırganın, aldatanın, Allah'ın yarattıklarına iftira edenin ve cehaletle konuşanın, dünyada aşağılandığında uğradığı aşağılanma tehdidinin bir parçasıdır!""")

# ───────── Sayfa 19 ─────────
h(19, 300, """{Allah kimi alçaltırsa artık ona ikram edecek kimse yoktur. Şüphesiz Allah dilediğini yapar}""")
h(19, 1400, """Yol arkadaşlığı olmadan yol çok zorlaşır; öyleyse benzerlerini nerede bulursan orası!""")
t(19, 2075, """Kardeşlerden biri az önce sordu: Ne yapalım?""")
h(19, 2350, """Dengeli ve hikmetli davranarak kendimizi insanlara altın tepside sunmayız!""")

# ───────── Sayfa 20 ─────────
t(20, 715, """İlmî emanet gereği, yapay zekânın sözü ..

Yağışlı çağlarda Arap Yarımadası'nın manzarası bugün gördüğümüzden tamamen farklıydı; su ve kara hayatıyla dolup taşan "yeşil bir cennet"ti.
İşte jeolojik ve arkeolojik delillere dayanarak o tarihî manzaranın ayrıntıları:

* Akan ve derin nehirler: Arap Yarımadası geniş bir tatlı su nehirleri ağını barındırıyordu. En meşhurlarından biri, yarımadayı batısından doğusuna kat eden eski "Rumme Nehri"dir.
* Devasa göller: Bilim insanları bölgenin dört bir yanına dağılmış on binden fazla eski gölün izlerini keşfetti. Bugünkü "Rub'ulhâlî" bölgesi bile geniş tatlı su gölleri ve bataklıklar içeriyordu.
* Ormanlar ve yeşil savan: Bildiğimiz gibi kum tepeleri yoktu; aksine uçsuz bucaksız yeşil çayırlar ve bugün Orta Afrika ile Hindistan'da bulunan ormanlara benzeyen sık ormanlar vardı.
* Hayret verici bir yaban hayatı: Yarımada, bugün ancak Afrika ormanlarında gördüğümüz hayvanların yurduydu; örneğin:
* Filler ve zürafalar.
* Nehirlerde ve göllerde yaşayan su aygırları ve timsahlar.
* Arap savanına yayılmış aslanlar, kaplanlar ve kurtlar.
* Düzenli yağmurlar: Yağmurlar yalnızca kışın değil, yılın bütün mevsimlerinde bolca yağıyordu; bu da bölgeyi o zaman insan ve hayvan hayatı için en uygun yer yapıyordu.

Bu ilmî tasvir, şu nebevî hadisle hayret verici biçimde örtüşmektedir: "Arap toprakları yeniden çayırlara ve nehirlere dönmedikçe kıyamet kopmaz"; bilim insanları bunu, yeryüzünün geçirdiği tabii iklim döngülerine bir işaret olarak görmektedir.""")

# ───────── Sayfa 21 ─────────
t(21, 100, """Sakın onu insanlara altın tepside sunma; çünkü acımasızca, kesen her şeyle üzerine çullanırlar.""")
h(21, 500, """İyi nefis büyük bir güçtür; onu yitirenler ondan haberdar olsaydı onun için savaşırlardı!""")
t(21, 1300, """Yeryüzünde binlerce kral vardır; yürüdüklerinde yeryüzünde vakarla yürürler, çünkü kral olduklarını bilirler. Ceplerinde günlük azıkları varken kralların tebessümüyle gülümserler. Uykuya çekildiklerinde vehim dairelerinde değil, Yüce Allah'ın melekûtunda dönüp durarak uyurlar. Akılları nefsin istekleriyle değil, göğün muratlarıyla meşgul olur. Çünkü bu, gezinti olarak değil mücâhede ederek yürümen gereken bir yoldur; ondan, burada yeryüzünde var oluşunun değerini öğrenirsin. Sonu kara âkıbetten başka bir şey olmayan taklide "hayır" demedikçe de kurtulamazsın!""")
h(21, 1900, """Nefis hiçbir kaderi değiştiremez; sahibini bir milyon faydasız denemede sıkıp ezer!""")

# ───────── Sayfa 22 ─────────
h(22, 400, """Nefis aklın gemidir; doğruyu görmeyi engeller, tedebbürü öldürür, kitlelerin düşüncesine sürükler, hatayı miras alma metodunu kökleştirir!""")
t(22, 1240, """Allah Teâlâ'nın gücü, kudreti ve dilemesiyle; Allah Teâlâ'nın gücüyle insanlara yeni bir seviye geliyor; bu geçen gecenin rüyasına dayanarak. Bu, Allah Teâlâ'nın izniyle hak bir rüyadır; çünkü onu görmemden birkaç saat sonra fiilen gerçekleşti! Bugünün yeni paylaşımlarında gerçekleşti.

Rüyada gelenlerden bir kısmı:
🟢 İnsanların bütün sınıfları ve tabakaları inşallah dinliyor
🟢 Rüyadaki gibi, dinleyenlerin çoğu, belki %98'i toplumların zayıflarındandır
Onlara yayımlanan ise fikir ve hikmettir
🟢 Allah'ın izniyle yayımladığım şeyin, doğruyu ve yanlışı anlamada Yüce Kitap'tan isabetli anlayışla aydınlanmasının tamamlanması; Rabbimiz Yüce Allah'tan sebat, isabet ve tevfik dilerim. Zira rüyada minberde söylemem gereken söz bir mushafın iki kapağına dönüştü (Fâtiha ve ilk sayfa, Bakara'nın başı).
🟢 Minber, büyük bir mescit binasının içinde bir odadır; odanın camdan bir kapısı vardır ve oda minberin yeridir""")
h(22, 2100, """Bu gece bana yeni bir fikir seviyesi gösterildi; onu insanlar arasında yayacağım ve Allah Teâlâ'nın gücüyle hâkim olacak""")

# ───────── Sayfa 23 ─────────
t(23, 225, """Az önce Yüce Rabbimizin Kitabı'nın âyetlerinden bir âyet üzerinde tedebbür ederken; tefsir âlimleri (Allah Teâlâ onlara rahmet etsin), isimleri ve sıfatları mukaddes olan Allah Teâlâ'nın sözü hakkında, Yüce Rabbimizin şu sözündeki (hüküm) için şöyle demişlerdir:
{İşte onlar, kendilerine Kitap, hüküm ve peygamberlik verdiğimiz kimselerdir. Eğer şunlar bunları inkâr ederlerse, biz bunlara, onları inkâr etmeyecek bir kavmi vekil kılmışızdır}

Oysa Peygamber Dâvûd, Peygamber Süleyman ve Peygamberimiz Muhammed (Allah'ın salât ve selâmı üzerlerine olsun) dışındaki peygamberler hükümdar olarak hükmetmediler .. Tefsir âlimleri, hükümden kastın hikmet olduğunu söylediler; başkaları ise hükmün insanlar arasında hüküm vermek olduğunu söyledi; bu ise bütün peygamberlerde gerçekleşmiş değildir. Nice peygamberle kavmi alay etti, onlara azap geldi ve peygamberlerinin en basit şeylerde bile aralarında hüküm vermesini kabul etmediler; aksine peygamberlerini hor gördüler ve onlara kötülük ettiler. Bir başka görüş de peygamberlere verilen hükmün Kitab'ı anlamak ve bilmek, yani fıkıh olduğudur.

Âyet-i kerîmede peygamberler hakkında geçen "hüküm"ün anlamı konusunda söylemek istediğim şudur — ilim yalnızca Rabbimiz Allah'a aittir; bu benim özel anlayışımdır, Allah Teâlâ'nın lütfuyla yazdığım her şey gibi onu bir yerde okumadım —: Âyet-i kerîmede geçen hüküm fıkıh değildir, hikmet de değildir; çünkü Kur'an kelimelerinde ve lafızlarında titizdir. Davalılar arasında hüküm vermek de değildir; çünkü bu, peygamberlerin çoğu için gerçekleşmemiştir. Hükmün bundan daha derin bir anlamı vardır.

Peygamberler hakkında geçen Kur'ânî lafzın (hüküm) anlamının derinliğini anlamak için peygamberlerin (aleyhimü's-selâm) hayatlarını izlememiz ve onların (aleyhimü's-salâtü ve's-selâm) âkıbetlerinde tekrarlanana bakmamız gerekir; orada şu meseleyi buluruz: tehlikelerden kurtuluş .. Allah Teâlâ peygamberlere kendisine dua etme gücünü verip de duaları hemen kabul edildiğinde, bu yeryüzünde büyük bir mülktür. Bu, yeryüzündeki mülk ve hüküm şekillerinin en yücesi ve en büyüğüdür.

Musa'nın (a.s.) mülküne, gökten desteklenen o hükme ve Firavun'un yeryüzüne ait mülküne bak; hangisi gerçekten yeryüzünde hükümdar ve kraldı?! Açıktır ki o, Allah'ın peygamberi Musa'ydı (a.s.).

Allah'ın peygamberi Sâlih'in güçlü kavmi üzerindeki mülküne bak. Sonunda zafer kazanan ve kurtulan kimdi? Allah'ın peygamberi Sâlih (a.s.) değil mi?

Allah'ın peygamberi İsa'nın çarmıhtan kurtuluşuna bak? Öyleyse gerçek anlamda hükümdar kimdi? Romalı vali mi, yoksa Allah'ın peygamberi İsa mı?

O gün bir imparatorluğa hükmeden Nemrud'un karşısında Allah'ın peygamberi İbrahim'e bak! Yeryüzünde, Allah'ın dilediğini desteklediği gerçek hükümdar kimdi? Nemrud'un iradesi mi gerçekleşti, yoksa Allah'ın peygamberi İbrahim'in (a.s.) iradesi mi?

Kureyş'in yıllarca Yarımada Arapları üzerindeki zorbalığına, gücüne ve satvetine bak? Sonunda zafer kazanan kimdi? Peygamberimiz (s.a.v.) değil mi?

Buradan açıkça anlarız ki peygamberler yeryüzünde gerçek krallar ve gerçek hükümdarlardı. Mecazen değil, hakikaten hükümdarlar! Hükümdarın özellikleri nedir? Sebeplere emrettiğinde sebeplerin ona itaat etmesidir. Fakat peygamberlere (aleyhimü's-salâtü ve's-selâm) göğün icabeti verilmişti; böylece iki modelle karşı karşıya kaldık: gökten kesin olarak desteklenen hükümdardan bin kat daha zayıf bir yeryüzü hükümdarı! Öyleyse gerçek hükümdar kimdi?!

Bu yüzden, isimleri ve sıfatları mukaddes, göklerde ve yerde yüce, pek büyük bir yücelikle yüce olan Yüce Rabbimiz peygamberlere hüküm verdiğini söylediğinde, o hüküm ne hikmetti, ne dinde fıkıhtı, ne de çekişen iki kardeş arasında hüküm vermek için bir mecliste oturmaktı. Mesele anlamca bu kadar basit değildi; aksine o gerçek bir hükümdür. Yeryüzü sebepleriyle olan yeryüzü hükmüne karşılık gökten desteklenen bir hüküm. Tuhaf olan şu ki insanlar, yeryüzünün çok zayıf ve değersiz sebeplerine dayanan yeryüzü hükmüne dikkat ediyor da peygamberlere bahşedilen, gökle desteklenen hükme dikkat etmiyorlar!

Bu kıyasa göre, Allah Teâlâ'nın peygamberlerden olmayan velîlerine, onlara korku olmadığı ve üzülmeyecekleri yolundaki vaadi gelir. Bu yüzden eskiden, kabul edilen duanın yeryüzünde hüküm ve mülk anlamının en büyük temsili olduğunu zikretmiştim. Kimin, isimleri mukaddes olan Yüce Melik ile ilişkisi Melik'e hakiki bir kulluk ilişkisi ise, o kişi yeryüzünde hükümdar ve gerçek bir kral olarak taçlandırılır; sarayı ve ordusu olmadan bütün dünya ona boyun eğer; çünkü kuvvet sebeplere değil, tümüyle Allah'a aittir.""")

# ───────── Sayfa 24 ─────────
h(24, 300, """{İşte onlar, kendilerine Kitap, hüküm ve peygamberlik verdiğimiz kimselerdir. Eğer şunlar bunları inkâr ederlerse, biz bunlara, onları inkâr etmeyecek bir kavmi vekil kılmışızdır}""")
t(24, 800, """Yüce Allah'ın tevfiki yeryüzünün sırlarının en büyüğüdür; aklın değil, bedenin değil, aşiretin değil, insanların sana desteği değil, sebeplerin sana icabeti de değil; çünkü sebeplerin icabetlerinin çoğu fitne ve istidracdır .. Tevfikin delili görünürdeki başarı değildir .. mal .. işler .. villa .. lüks araba .. Bunların hepsi yanlış anlayıştır .. Tevfikin delili, dünya yurdunda mutmain olan nefistir .. Çok fakir, bedbaht zavallının nefsi ise razı olmadıkça mutmain değildir .. Yeterli geçim lüks değildir; Allah Teâlâ bizi fakir ve yoksul olarak değil, yeterli geçimle yaşayalım diye yarattı; Peygamber'in (s.a.v.) bize öğrettiği de budur. Öyleyse tevfik, yeterli geçime rıza ve rıza ile birlikte yeterli geçimdir; böylece nefis mutmain olur. Ben eskiden beri, gündüzleri endişe, geceleri uykusuzluk olan mal sahipleri bilirim! Bu tevfik midir? Hayır vallahi .. Bu, tevfik gösterisidir; insanlara muvaffak olduklarını oynuyorlar ve insanlara mutlu olduklarını oynuyorlar; fakat insanların çoğu bilmez. Eşyayı ve hakikatini bilen ile onları bilmeyen aldanmış kişi arasında ne büyük fark var. Karun'a gelince, o asla muvaffak değildi; ibret alın, çünkü mümine ahmak olmak yakışmaz!""")
h(24, 1500, """Yeryüzünün sırlarının en büyüğü!""")
t(24, 2315, """Yüce, kerîm bir Rab; peygamberleri ve kitapları gönderdiğinde bu, insanlar ve onlarla birlikte cinler için büyük bir nazlandırmaydı .. Yüce Rab kullarının işini önemser .. Onların dünyada ve âhirette saadetini önemser .. Fakat insanların çoğu bu nazlandırmayı görmedi, kavramadı, anlamadı; ne yazık ki onun gerçekten bir nazlandırma ve şımartma olduğu hakikatini kavramadılar; onu, arzuladıkları haram lezzetlerden bir ceza ve mahrumiyet olarak aldılar. Böylece kerîm Rablerinden anlamada hata ettiler; hayatlarını gerektiği ve lazım geldiği gibi anlamadılar; bu yüzden hoş, arı, saf, temiz bir hayat yaşamadılar. Çünkü kısıtlama sandıkları şey, Âdem'den (a.s.) beri daima bir nazlandırmaydı; zira Yüce Rabbimiz bizim için villalarda ve saraylarda yaşamamızı, yiyip de yorulmamamızı, yiyip de sağlıklı olmamızı, birbirimize buğzetmememizi ve kavga etmememizi, insanların binlerce güzel şeyden faydalanmasını diledi. Yüce Rabbimiz, takvâ sahibi kullarının …""")

# ───────── Sayfa 25 ─────────
t(25, 60, """… dünya yurdunda hoş bir hayat yaşayacaklarını kararlaştırmıştır. Fakat insanlar Kur'an'ı Allah'tan bir sevgi ve muhabbet mektubu olarak görmediler; hepsi değil ama çoğu onu bir kısıtlama ve tahakküm mektubu olarak gördü. Böylece huzursuzlandılar ve Rablerinden, geçmiş kölelik devirlerindeki kaçak bir köle gibi kaçtılar; uğursuz köleler kulağına fısıldayıp ona dediler ki: "Efendilerimizle bize hayat yok; özgürlük onlardan iyidir." Gece vakti adımlarını hızlandırdılar; onları yol kesiciler karşıladı ve yeniden köleleştirdi. Oysa dün, onlara köle muamelesi değil dost muamelesi yapan efendilerin yanında ikram görüyorlardı. Allah Teâlâ'ya kulluk; tam bir şeref, eksiksiz bir izzet ve kesin bir kurtuluş olan tek kulluktur. Çünkü Rabbimiz Yüce Allah'ın biz gerçekten kullarıyız; fakat O'nun yüce öğretileri bizi yeryüzünde ikram gören efendiler olarak yaşatır; Yüce Rabbimiz, O'na itaat ettiğimizde bizi efendilik, izzet ve yüksek değerle destekler. Bu ise, Allah'ın Kitabı'nı hapishane zincirleri olarak gören, Allah'ın Kitabı'ndan kaçan kimsenin hiçbir şey elde edemeyeceği şeydir; o, yönü olmayan, seraptan başka bir şeye ulaştıracak yolu bulunmayan bir kaçak olarak yaşayacaktır.""")
h(25, 800, """Rabbimizin Kitabı'nda olduğu gibi her güzel şeyin emredilmesi, Kur'an'ın insanlara inmesini, insanların Allah Teâlâ katındaki nazlandırılmasının zirvesi kılar""")
t(25, 1485, """Adama (Allah ona rahmet etsin) karşı; beslenme cahili, insan bedeninin yaratılış tabiatının cahili, mantıktan yoksun, cehaleti benimseyip insanlar arasında yaymakta ısrar eden, insanların kendilerini alkışladığını iddia eden kimselerden gelen ahlâk dışı bir saldırı. Bunlar gülünç ve ayıp cambazlık gösterileridir. Haberden önce izi sorma; çünkü adamın, şeker, konserve tüketimi ve sigara konusunda onunla ihtilafıma rağmen, ölümünden sonraki izi haberin ta kendisiydi! Doğru ve isabetli olan sözü fette ziyafetlerini bozacak! Fette ise göbeklere hiç de önemsiz değildir. Haydi gelin şöyle diyelim: Adam İslâm'ı düşürdü ve can evinden vurdu, dini yıktı, Endülüs'ün, Kudüs'ün ve Bağdat'ın işgaline sebep oldu; laf olsun diye ne laf olursa. Önemli olan gevezelik etmek, gevezelik etmek ve konuşmaktır. Allah size hayırlı sabahlar vermesin!""")
h(25, 2200, """Evet, o (Allah ona rahmet etsin) doğru söyledi; fette göbekleri ise yalan söyledi. Aç kalmak için yaratıldık!! Peygamberimiz (s.a.v.) de böyle yaşadı""")

# ───────── Sayfa 26 ─────────
t(26, 360, """Almanya veya Japonya gibi bir devlet, cihazın 30 yıl yaşadığı aletler üretmekle övünür ve "yüksek kalite" derler; sonra aynı maddî dünya, 1945 dünyasının dönemi ve çağı boyunca insanlara şunu söylüyordu: Kalpleriniz, pankreaslarınız, karaciğerleriniz, böbrekleriniz, akciğerleriniz, bağırsaklarınız ve bedenlerinizin içindeki diğerleri yaşınız ilerledikçe yaşlanır!!! Yalan söylediler ve insanlara çokça yalan söylemekle suç işlediler.

Siz yüksek kaliteli cihazlar üretiyorsunuz ve seksen yıl boyunca insanları, insan bedeninde yüksek kalite olmadığına ikna etmek için çalıştınız! Allah sizin iftiranızdan pek büyük bir yücelikle yücedir! İnsanlara dediniz ki: Ürettiğimiz televizyon cihazlarının parçaları, ürettiğimiz pahalı arabaların parçaları, ürettiğiniz çok pahalı telefonun parçaları, fiyatı 100 bin dolar olan çanta ve yüksek kaliteli ürünlerimiz yaşlanmaz, iç organları bozulmaz; Yüce Yaratıcı Rab ise iç parçaları düşük kaliteli, yaş ilerledikçe yaşlanan, bozulan ve arızalanan bir insan yaratmıştır. Yalan söylediniz. İnsanın iç parçaları asla ve kesinlikle yaşlanmaz; ruhun çıktığı ana ve vefat anına dek %1000 verimle çalışmaya devam eder. Fakat onları arızalandıran ve bozan, 1945 dünyasının beslenme düzeniyle sizsiniz. Delil hem uzakta hem yakındadır: 70 yaşında son derece yorucu ve meşakkatli savaşlara giren sahâbîler ve daha dün, 70 yıl önce sıfır hastalıkla ölen dedelerimiz!

İsimleri ve sıfatları mukaddes, göklerde ve yerde yüce olan Rabbimiz Yüce Allah bedenlerimizi yüksekten de yüksek bir kaliteyle yarattı; bu yüzden karaciğerin, miden, pankreasın, bağırsakların, akciğerin ve kalbin yalnızca 70 yıl için değil, bin yıl boyunca %1000 verimle çalışmak üzere yaratıldı .. Uyan""")
h(26, 1500, """Televizyonu muazzam kalitede üretiyorlar ve insana diyorlar ki: Bedeninin cihazları yaşınla birlikte yaşlanır!!""")
t(26, 2325, """Peygamberler için vahiy .. Islah ediciler için ise onları inşa eden, yapan ve bâtılı kendi gözleriyle müşahede edecek dereceye dek cilalayan tecrübeler!""")

# ───────── Sayfa 27 ─────────
h(27, 300, """Yeryüzünde hak, ancak bâtılın kökü bilinerek ayakta tutulur!""")
t(27, 805, """Keşfedilen ve dinozorlara ait olduğu söylenen iskeletler hakkında soruldum!
Uzayda unutulmuş yeryüzü hikâyesinin arkasındakiler bunu söylemek istemediler! O iskeletlerin dinozorlara ait olduğunu söylemeleri gerekiyordu; çünkü sürüngenler, devasa olsalar bile, insan onların üstesinden gelebilir ve onları öldürmek için sözde bir dış uzaydan gelen meteorlara ihtiyaç duymaz; bu da onların anlatısına hizmet etmez. Dinozorlar ise, sunuldukları şekliyle, çok devasa yaratıklardır; yeryüzündeki hayatı onların varlığı gölgesinde başlamışsa insanın onlarla baş edememesi tabiidir. Bu yüzden onlar ancak bütün yeryüzünü yok eden veya dinozorları yok edip yeryüzünü bırakan meteorlarla son bulur. İşte bu yüzden onların dinozor iskeletleri olduğunu söylemeleri şarttı; fakat ne yazık ki küçük dinozor iskeletleri bulduk ve size söz veriyoruz, 10 bin yıl sonra sizin için büyük dinozor iskeletleri bulacağız; yeter ki bizimle olun!""")
h(27, 1400, """Keşfedilen bütün iskeletler devasa sürüngenlere aittir!""")
t(27, 2235, """Takipçilerden biri bana dinozor hikâyesinin uydurulma sebebini sordu. Cevap çok kısaca şöyle

Dinozor meselesi, yeryüzünün küre olduğunu ispat etmek ve yeryüzünün üstünde bir uzayın ve boşluğun varlığını ispat etmek için çok önemlidir .. Semavî dinler yeryüzünün bir kubbeyle kapatılmış bir düzlem olduğunu açıkça ortaya koymuştur; dinozorlar ise onların iddia ettikleri anlatıya göre uzaydan bombalanmıştır. Dolayısıyla dinozorlar onlar için yeryüzünün küre olduğunun delili ve yeryüzünün üstünde bir boşluğun bulunduğunun delilidir; böylece yeryüzünün uzayda asılı, unutulmuş, terk edilmiş, yaratıcının umursamadığı bir küre olduğunu ispat ederler ve bununla aslen bir yaratıcının olmadığına delil getirirler. En iyi ihtimalle de Batı gençliğine, sonra Doğu'ya şöyle derler: Yaratıcı, onların çizdiği gibi engin uzayda asılı, toz zerresi büyüklüğünde bir küreyle ilgilenmeyecektir. Bu, yeni bir bilinç inşa etmek için önemli bir psikolojik etkidir; o da (dinsizliktir). Çünkü bir bahçede uyuyan kişi, insanların gözünde dağınık, saçı başı karışık, toz toprak içinde, saygın olmayan bir insandır; oysa""")

# ───────── Sayfa 28 ─────────
t(28, 60, """bir evde uyuyan kişi düzenli ve saygın bir insandır. Yeryüzü ise onların söylediğine göre uçsuz bucaksız geniş bir evrende, uzayın ortasında saçı başı dağınık, toz toprak içinde uyumaktadır. Bu yüzden Batı'ya, sonra ardından Doğu'ya, büyüklüğü yokluğa yaklaşan, bir mahlûk olarak saygıyı hak etmeyen bir şey olarak sunuldu. Bu, dünya teknolojisine hâkim olan Batılı kişiliğin inşası için önemlidir; çünkü onun dünyaya önderlik edecek bir kişilik olduğunu biliyorlardı. Yaratıcıya dair çarpık bir bilinç inşa etmek için önemlidir. Fakat şeytanın yeryüzüne hükmetmesi için Batılı kişiliğin dinsiz veya dine kayıtsız kılınması şarttı; ta ki dünya tek bir köye dönüştürülebilsin. Çünkü dinin, küreselleşmenin açılmasına, kurulmasına ve yayılmasına — onların istediği küreselleşmeye — katkıda bulunmayan esasları vardır. Bu yüzden dinin, dünyanın önderlerini (Batı'nın gençlerini, erkeklerini ve kadınlarını) etkilemekten uzak tutulması şarttı; ki küreselleşme inşa edilsin. Çünkü her semavî din küreselleşmeye karşı bir set duvarıdır. Onlar küreselleşmeyle, en genç kuşakları değiştiren tek, ortak, küresel ahlâkî değerler yaymak istediler ve bunda küreselleşmenin çok güçlü kolu (internet) aracılığıyla başarılı oldular. Bunu, yani tek, kolektif, küresel bir bilinç inşasını, dinleri — bu arada İslâm'ı da — yenilgiye uğratmak amacıyla istediler. Bu yüzden Müslümanlar bile birleşmemişlerse, yok edilmeye ve tüketilmeye çok elverişli hale gelirler; bu bir hakikattir. Saçma dinozor hikâyesinin arkasındakiler bunu bilirler ve Müslümanların asla birleşmeyeceği “vehmine” kapılmışlardır; bu vehme dayanırlar. Özet .. Dinozorlar, büyük saçma hikâyenin en saçma parçasından başka bir şey değildir.""")
h(28, 1000, """Dinozorlar ve saçma hikâye!""")
h(28, 2100, """Hiçbir dinozor yoktu!""")

# ───────── Sayfa 29 ─────────
t(29, 225, """Zararlı yiyecek yemek ise iltihabı geri getirir .. Mesele şaka değil .. Mesele gerçek""")
h(29, 600, """Mesele gerçektir, vehim değil. Tecrübe: Zararlı gıdayı bırakmak bedendeki iltihapları durdurur!""")
t(29, 1435, """Bozuk satıcının insanlara bozuk yiyeceği onun sayesinde sattığı sır! Doğru yolda yürüdüğünü sanan bir insanın hayatının onun sayesinde çalındığı sır! Zararlı gübre ve zararlı gıda satarak milyarlar kazanmamızı, hatta milyonlarca yoksula vehim satmamızı, üstelik onları kendilerine sattığımız bâtılın azılı savunucuları yapmamızı mümkün kılan sır! Şimdi cehaletin ne kadar güçlü olduğunu anladın mı?! Gıda hakkındaki ve hayât-ı tayyibenin gerçek ölçüsü hakkındaki cehalet; 1945'ten beri milletlere sirayet etmiş olan o cehalet ki gücü, kitaplardaki ilimden daha büyüktür! O, uyaranların ve sakındıranların haykırışından daha yüksek sesli bir cehalettir. İnsanların cehaleti, 1945 Matrisi'nin başarısının en büyük sırrıdır!

1945 Matrisi, başarısının, insanlar arasında ilmi değil cehaleti yayarak hâkim olmak ve insanları yalanlara inandırmak için radyoya ve televizyona ihtiyaç duyduğunu çok iyi biliyordu; çünkü o, cehaletin gücünü çok iyi kavrayan bir matristir! Yalanların en basiti, insanların ambalajların üzerinde yazan her şeye inanmasıdır: (sağlıklı) - (taze) - (doktorlar tavsiye ediyor) - (doğrudan çiftlikten)!! Sonra interneti serbest bıraktı ve onun kendisini rezil edeceğini bile bile buna izin verdi; fakat özgüvende öyle bir dereceye ulaşmıştı ki aldırmaz hale gelmişti! 1945 Matrisi bugün, insanlığın geç edindiği bir bilinçle savaşıyor; çünkü o, her şeyin yeryüzüne ait olduğunu sanan ve bu yüzden kendini güvende hisseden bir matristir!""")
h(29, 2300, """İlmin tek başına güçlü olduğunu mu sanıyorsun? Hayır, cehaletin gücü, ilmin gücünün etkisinden daha büyüktür!""")

# ───────── Sayfa 30 ─────────
t(30, 515, """Pek çok eski kayıtta gençlere söylediğim şey; “Su neden ucuz, elmas neden pahalı?” şeklindeki eski soru, fiyatlandırmada marjinal değer kavramına dair anlaşılması gerekenin ta kendisidir. Bu yüzden hayat, sebepleri ve sebeplerinin hareketi bakımından, büyük bir yönüyle marjinal değer kavramı esası üzerine kuruludur: Su çok boldur ve elde edilmesi mümkündür, bu yüzden fiyatı ucuzdur; elmas ise nadirdir ve suyun bolluğu gibi bol değildir, bu yüzden fiyatı çok yüksektir. İşte bu sebeple genç, inşa etmemek ile inşa etmek, cehalet ile ilim, kabiliyetsizlik ile kabiliyetler arasındaki farkı idrak etmeli; kendini ve zâtını inşa etmelidir. Zira inşaat işçisi, zihnî becerilere sahip bir memurdan çok daha büyük bir çabayla çalışır; ama inşaat işçisinin maaşı memurun maaşından çok daha azdır.""")
h(30, 1200, """Marjinal değer, hayat manzarasının önemli bir bölümünü yönetir. İktisat teorileri, hayat bilincini inşa etmenin hizmetinde!""")
t(30, 1940, """İnsanlar, sahâbenin ve tâbiînin hayatının tersine, gece gündüz çekişip kavga ediyor .. Kavga etmeyin; çünkü bedenlerinizi mahvediyorsunuz""")
h(30, 2300, """Bir insan sağlığını mahvetmekte ısrar ettiğinde, bil ki o, rolünün bu olmasına karar vermiştir!!""")

# ───────── Sayfa 31 ─────────
t(31, 615, """4 yıldır söylüyorum ve defalarca tekrarladım: Dinde, müzmin ruhî eziyete maruz kalmanı haklı çıkaracak hiçbir şey yoktur; çünkü bedeli, abartısız, çok ağırdır""")
h(31, 1100, """Bir dakikalık huzursuzluk ve gerginlik = beden sağlığı için sefil bir ay""")
h(31, 2200, """Şeker - beyaz un - konserveler - sigara - ağırlık sporu yok: Çok sefil ve başarısız bir evlilik hayatı!""")

# ───────── Sayfa 32 ─────────
h(32, 700, """Yemeyi bırakmayan bir ağız! Hasta beden = bitkin nefis = yorgun ruh = ibadetlere güç yetirmede zayıflık = Allah Teâlâ ile ruhî bağda zayıflık!""")
t(32, 1445, """Tavuğun evcilleşmeyle ve himmetin yokluğuyla ilişkisi! Bu paylaşım, onu gıda olarak benimsemekten, tekrarlamaktan, çokça yemekten veya zararı sabit olduğu halde tüketmekten söz ediyor.

Özgür kuş, kayıtsız hareket serbestliği bakımından koyuna, keçiye ve deveye benzer; çobanlar bunu Peygamber'den (s.a.v.) önceki devirden beri bilirler. Dolayısıyla havadaki özgür kuş, yeryüzündeki özgür hayvanların, koşan ve hareket eden deve ve koyunların benzeridir; hapsedilmekle göğsü daralan tavuğun hapsi gibi hapsedilmez. Modern bilimin söylediklerinden biri de budur. Peki çokça tavuk yiyenler için insan davranışı üzerinde gerçekten bir etki var mıdır?!

İbn Teymiyye (Allah ona rahmet etsin), insanın yediği şeyden etkilenmesi hakkındaki uzun bir sözünde şöyle der; anlamını şu şekilde özetleyebilirim: “Gıda, insanın cevherinden bir parçaya dönüşür”; dolayısıyla gıda belirli sıfatlar taşıyorsa bu sıfatlar insanın nefsine ve bedenine sirayet eder.

İbn Teymiyye, hayvanlarla iç içe olmanın nefisteki etkisini açıklayan, üzerinde ittifak edilmiş bir hadisle delil getirmiştir. Hadis: Peygamber (s.a.v.) şöyle buyurdu: “Övünme ve kibir deve sahiplerinde, sükûnet ve vakar ise koyun sahiplerindedir.”

İstidlâl yönü: İbn Teymiyye'ye göre, sırf bu hayvanlarla iç içe olmak ve onları gütmek bile bu sıfatları kazandırıyorsa, insanın bedeninden bir parçaya dönüşen etleriyle beslenmenin etkisi daha güçlü ve daha nüfuzlu olur.

Deve etinden dolayı abdest alma emri
İbn Teymiyye, devenin “gıdaî” etkisini açıklamak için, koyun etinden değil de deve etinden dolayı abdest almayı emreden hadisleri delil getirmiştir.

Hadis: Resûlullah'a (s.a.v.) soruldu: “Deve etinden dolayı abdest alayım mı?” Buyurdu ki: “Evet, deve etinden dolayı abdest alın.” Koyun eti hakkında sorulunca da “Hayır” buyurdu.

İstidlâl yönü: İbn Teymiyye, devenin şeytanlardan yaratıldığını (yani onda ürkeklik ve şeytanlık bulunduğu anlamında), etini yemenin şeytanî bir kuvvet, kin ve kalp katılığı kazandırdığını zikretmiştir; bu yüzden şeriat, ateşin abdestle söndürüldüğü gibi, o kuvveti suyla söndürmek için ondan dolayı abdest almayı emretmiştir.

Azı dişli ve pençeli hayvanları yemenin yasaklanması""")

# ───────── Sayfa 33 ─────────
t(33, 60, """Âlimler, yırtıcı hayvanları yemenin haram kılınması ile onların saldırgan tabiatlarının kazanılması arasında bağ kurmuşlardır.
Hadis: “Resûlullah (s.a.v.), yırtıcı hayvanlardan azı dişi olan her hayvanı ve kuşlardan pençesi olan her kuşu yasakladı.”
İstidlâl yönü: İbnü'l-Kayyim ve İbn Teymiyye, haram kılmadaki hikmetin, onlarla beslenenin “yırtıcılık kuvveti” kazanabilmesi olduğunu zikretmişlerdir; bu da ona azgınlık, saldırganlık ve parçalayıcılık ahlâkını kazandırır.

Domuzun haram kılınmasına dair hadis
Haram kılma Kur'an'da açıkça geçmekle birlikte İbn Teymiyye, illetin onun yediğinin pisliğinde olduğuna işaret etmiştir; bu da, pis şeylerden kaçınmaya dair nebevî kaideye kıyasla, onu yiyenin tabiatına deyyusluk ve kıskançlığın gitmesi şeklinde yansır.""")
h(33, 800, """Özgür kuşun Filistin'le ilişkisi: Allah'ın peygamberi Musa'nın nesli Filistin'i fethetmekle mükellef kılındı; özgür kuşlarla beslendiler, ama onu reddedip tersini istediler!""")
h(33, 2000, """Xi – Trump görüşmesi: Önemli sözler yardımcılar hazır bulunmadan söylenecek ve kelimenin tam anlamıyla tarihî atışmalara sahne olacak!""")

# ───────── Sayfa 34 ─────────
t(34, 85, """Belki""")
h(34, 500, """Xi – Trump görüşmesi: Belki insanlar, sarayın şekli veya kasıtlı mesajlar taşıyan geleneksel tarihî semboller gibi tarihî görünümlere tanık olacak!""")
h(34, 1600, """Xi – Trump görüşmesi: 2022'den beri kararlaştırılmış bir zirve!""")

# ───────── Sayfa 35 ─────────
h(35, 300, """Xi – Trump görüşmesi: O, Xi ile bir Amerikan, Alman, Fransız görüşmesidir!""")
t(35, 915, """Gıda hakkında bir videoyla çıktı; içinde, İblis'in bile Âdem'in oğullarına ve kızlarına zarar vermek için söylemeyi hayal etmediği şeyleri söyledi! İçinde acayiplikler ortaya koyduğu ve kendisinden önce kimsenin getirmediği yanlışları kesinlediği bir video; bunların cehaletçe en büyüğü, dünya ilaç şirketleri için söylediği şu sözdür: Onlar uzman tıp kurullarıdır; bir şeyin kanserojen olduğunu söylememişlerse o kanserojen değildir!! Koyu bir cehaletle dolu, teorilere değil bilimsel gerçeklere aykırı olan her şeyle dolu, felaket bir video. Söylediği felaketlerden biri: Bitkilerin ve tavukların büyümesini hızlandıran hormonların ve maddelerin kullanılmasında ne sakınca var! Dünyanın bütün doktorlarının yasakladığı beyaz un hakkında da Vecdi şöyle diyor: “İnsanları niye mahrum ediyorsunuz?!” İşte bu, konuşma şehvetidir; her şey hakkında konuşma ve her konuda fetva verme sevdasıdır; öyle ki iş, insanların sağlığına ve hayatına zarar vermeye kadar varmıştır!

Ey insanlar! Ben tecrübeyle gördüm ki bu çağımızda insanların %99,9'u bâtıl söz ve düşünce üzere durmaktadır; bu yüzden konuşanlara hitap etmenin faydası yoktur. Onunla uzman doktorlar konuştu; nasihati reddetti ve cehalet yaymakta ısrar etti. Öyleyse kendiniz hakkında Allah'tan korkun ve anlamadığı şeyi bir şeyhten almayın.""")
h(35, 1800, """Ey Vecdi Guneym, Allah'tan kork! Kendi alanı dışında konuşan, musibetler getirir! Ey insanlar: Ona uyup da size dediği gibi her şeyi yemeyin!!""")
t(35, 2550, """Öfkeli biri, “Bir ölü hakkında ‘O şimdi hesaba çekiliyor’ demek caiz değildir” sözüme itiraz ederek yorum yazdı

Cevabı öğren ve insanları kutsama; hayır sahibi biri, cehaletiyle kutsal olmaz!""")

# ───────── Sayfa 36 ─────────
t(36, 95, """Cevap: İnsanın, belirli bir şahsın şu an belirli bir şekilde hesaba çekildiğini kesin olarak iddia etmesi caiz değildir. Bu, âlimler katında “Allah adına yemin edip hüküm vermek (teellî)” diye adlandırılır. Sahih hadiste geldiğine göre bir adam “Vallahi Allah falancayı bağışlamaz” demiş; bunun üzerine Allah azze ve celle şöyle buyurmuştur: “Falancayı bağışlamayacağıma dair benim adıma yemin eden de kim? Ben onu bağışladım, senin amelini ise boşa çıkardım.”

Özet: Ölünün başına gelenlerin ayrıntıları hakkında kesinlik yoluyla “kesin hüküm vermek” şer'an sahih değildir; çünkü bunlar gaybdır. Doğru söz, ona sebat ve rahmet için dua etmek ve Allah'ın kulları hakkındaki hükmüne muttali olunduğunu ima eden ifadelerden kaçınmaktır.""")
h(36, 800, """Öfkeli birinden itiraz. Birinin “Falanca şimdi hesaba çekiliyor!” sözünde Allah adına hüküm verme vardır""")
h(36, 2000, """{Onlar tuzaklarını kurdular; oysa tuzakları Allah katındadır; tuzakları dağları yerinden oynatacak olsa bile. Sakın Allah'ı, peygamberlerine verdiği sözden cayar sanma. Şüphesiz Allah azîzdir, intikam sahibidir} (46-47)""")

# ───────── Sayfa 37 ─────────
h(37, 500, """{Allah, iman edenlerin velîsidir; onları karanlıklardan nura çıkarır. İnkâr edenlerin velîleri ise tâğuttur; onları nurdan karanlıklara çıkarırlar. İşte onlar ateş ehlidir; orada ebedî kalacaklardır} (Bakara Sûresi)""")
